 static Object staticField(Class<?> type,String name)throws Exception{var f=type.getDeclaredField(name);f.setAccessible(true);return f.get(null);}
 static Object call(Object target,String method)throws Exception{var m=target.getClass().getDeclaredMethod(method);m.setAccessible(true);return m.invoke(target);}
