  context.runOnClient(c->{try{var screen=(PrivateChatScreen)c.screen;var hit=((List<?>)WorldClientGameTest.field(screen,"hitRows")).getLast();int rowY=(Integer)call(hit,"y");int x=ArchiveLayout.of(screen.width).contentX()+80;click(screen,screen.winX+x*screen.windowScale,screen.winY+(rowY+15)*screen.windowScale,1);var menu=staticField(ChatAssist.class,"menu");var rows=(List<?>)call(menu,"rows");int index=-1;for(int i=0;i<rows.size();i++)if(call(rows.get(i),"label").equals("取消收藏"))index=i;check(index>=0,"★信息 row offers 取消收藏");int before=SavedChatStore.entries().size();ChatAssist.menuClick(screen,(Integer)call(menu,"x")+5,(Integer)call(menu,"y")+index*18+5,0);check(SavedChatStore.entries().size()==before-1,"取消收藏 removes it");}catch(Exception e){throw new AssertionError(e);}});
  context.runOnClient(c->c.setScreen(PrivateChatScreen.conversation(null,PaleTaleClient.MARKET,"领地:高塔")));context.waitTicks(3);context.takeScreenshot("chat-104-muted-conversation");
  context.runOnClient(c->{PrivateChatStore.toggleMute("领地:高塔");check(!PrivateChatStore.muted("领地:高塔"),"mute toggles off");c.setScreen(new net.minecraft.client.gui.screens.TitleScreen());});
